import * as React from "react"
import { graphql, useStaticQuery } from "gatsby"
import { SHARE } from "../config/share"

/**
 * `noindex` is for pages that exist but are nobody's business to find: the
 * admin workbench, and the help page for somebody locked out (which is only
 * useful arriving from a receipt or from us). It is a request, not a control —
 * anything genuinely private needs the gate, not the meta tag.
 *
 * ── LINKS DROPPED INTO A CHAT — FCS-126 ────────────────────────────────────
 * Every page carries the share card (picture, title, words) so a link pasted into a message, a post or a
 * group opens as a card, not as a bare address. `path` is the page's own address ("/qr-codes/"): it makes
 * the card and the search result point at THAT page instead of at the home page, which is what every page
 * said before. `fullTitle` replaces the "Page | Site" pattern (the home page uses it), and `schema` is
 * structured data for search engines (the home page describes the site and its tools).
 */
const Seo = ({ title, fullTitle, description, noindex = false, path, schema }) => {
  const { site } = useStaticQuery(graphql`
    query {
      site {
        siteMetadata {
          title
          description
          siteUrl
        }
      }
    }
  `)

  const meta = site.siteMetadata
  const pageTitle = fullTitle || (title ? `${title} | ${meta.title}` : meta.title)
  const desc = description || meta.description
  const url = path ? `${meta.siteUrl}${path}` : meta.siteUrl
  // Versioned, so a changed picture is fetched again by apps that cache the old one for weeks.
  const image = `${meta.siteUrl}${SHARE.image}?v=${SHARE.version}`

  return (
    <>
      <html lang="en" />
      <title>{pageTitle}</title>
      <meta name="description" content={desc} />
      {path && !noindex ? <link rel="canonical" href={url} /> : null}
      <meta property="og:site_name" content={meta.title} />
      <meta property="og:title" content={pageTitle} />
      <meta property="og:description" content={desc} />
      <meta property="og:type" content="website" />
      <meta property="og:url" content={url} />
      <meta property="og:image" content={image} />
      <meta property="og:image:type" content="image/png" />
      <meta property="og:image:width" content={String(SHARE.width)} />
      <meta property="og:image:height" content={String(SHARE.height)} />
      <meta property="og:image:alt" content={SHARE.alt} />
      <meta name="twitter:card" content="summary_large_image" />
      <meta name="twitter:title" content={pageTitle} />
      <meta name="twitter:description" content={desc} />
      <meta name="twitter:image" content={image} />
      <meta name="twitter:image:alt" content={SHARE.alt} />
      <meta name="theme-color" content="#1668e8" />
      {noindex ? <meta name="robots" content="noindex, nofollow" /> : null}
      {schema ? <script type="application/ld+json">{JSON.stringify(schema)}</script> : null}
    </>
  )
}

export default Seo
