import * as React from "react"
import { PLAN_CHOICES, clearSandbox, setSandbox, stopViewAs, useSandbox, useViewAs } from "../lib/test-mode"
import * as s from "./ViewAsBanner.module.css"

/**
 * "You are looking at somebody else's account" — FCS-095.
 * ============================================================================
 * Shown at the top of every page, in the tab an administrator opened in test
 * mode, and nowhere else: the header renders it, and it renders nothing unless
 * THIS tab is viewing. It cannot be missed and cannot be mistaken for the
 * customer's own screen, which is the failure it exists to prevent.
 *
 * It carries the sandbox controls too, because going back to the admin tab to
 * change the pretend plan and then returning here to look is a slow way to try
 * three plans. Changing them re-draws the screen below (the account pages
 * listen for it); nothing is saved anywhere but the administrator's browser.
 */
const ViewAsBanner = () => {
  const view = useViewAs()
  const sandbox = useSandbox(view?.id)
  const [domain, setDomain] = React.useState("")

  React.useEffect(() => {
    setDomain(typeof sandbox.domain === "string" ? sandbox.domain : "")
  }, [sandbox.domain])

  if (!view) return null

  const domainMode = sandbox.domain === undefined ? "real" : sandbox.domain === null ? "none" : "has"

  const exit = () => {
    stopViewAs()
    window.location.assign(`/admin/users/#${view.id}`)
  }

  return (
    <div className={s.bar} role="status" data-testid="view-as-banner">
      <div className={s.top}>
        <strong className={s.tag}>Test mode</strong>
        <span className={s.text}>
          Viewing <strong>{view.email || "an account"}</strong> as they see it. Nothing here changes
          their account.
        </span>
        <button type="button" className={s.exit} onClick={exit}>
          Exit test mode
        </button>
      </div>

      <div className={s.controls}>
        <label className={s.field}>
          <span>Pretend plan</span>
          <select
            value={sandbox.plan || ""}
            onChange={e => setSandbox(view.id, { plan: e.target.value || undefined })}
            aria-label="Pretend plan"
          >
            <option value="">Their real plan</option>
            {PLAN_CHOICES.map(p => (
              <option key={p.id} value={p.id}>
                {p.label}
              </option>
            ))}
          </select>
        </label>

        <label className={s.field}>
          <span>Pretend domain</span>
          <select
            value={domainMode}
            onChange={e => {
              const mode = e.target.value
              if (mode === "real") setSandbox(view.id, { domain: undefined })
              else if (mode === "none") setSandbox(view.id, { domain: null })
              else setSandbox(view.id, { domain: domain.trim() || "sandbox-example.com" })
            }}
            aria-label="Pretend domain"
          >
            <option value="real">Their real state</option>
            <option value="none">No domain</option>
            <option value="has">Has a domain</option>
          </select>
        </label>

        {domainMode === "has" ? (
          <label className={s.field}>
            <span>Domain</span>
            <input
              value={domain}
              onChange={e => setDomain(e.target.value)}
              onBlur={() => domain.trim() && setSandbox(view.id, { domain: domain.trim() })}
              onKeyDown={e => e.key === "Enter" && e.currentTarget.blur()}
              placeholder="sandbox-example.com"
              aria-label="Pretend domain name"
              spellCheck="false"
            />
          </label>
        ) : null}

        {sandbox.plan !== undefined || sandbox.domain !== undefined ? (
          <button type="button" className={s.reset} onClick={() => clearSandbox(view.id)}>
            Reset
          </button>
        ) : null}
      </div>
    </div>
  )
}

export default ViewAsBanner
