import * as React from "react"
import { Link } from "gatsby"
import { HardHat, ArrowRight } from "./Icons"
import { useAuth } from "../context/auth"
import ViewAsBanner from "./ViewAsBanner"
import { useViewAs } from "../lib/test-mode"
import { useStartCta } from "../lib/start-cta"
import { useDisplayName } from "../lib/display-name"
import * as s from "./Header.module.css"

const LINKS = [
  { label: "Free Services", href: "/#services" },
  { label: "Website Builder", href: "/website-builder" },
  { label: "Invoice Builder", href: "/invoice-builder" },
  { label: "QR Codes", href: "/qr-codes" },
  
]

const Header = () => {
  const [open, setOpen] = React.useState(false)
  const { user, ready, available, isAdmin } = useAuth()
  // While looking at somebody else's account the screen has to look like THEIRS,
  // so the administrator's own shortcuts stay out of it.
  const viewing = useViewAs()
  // "Get Started Free" is for somebody who has not started — FCS-103.
  const cta = useStartCta()
  // Who is signed in, so the header says so instead of a bare "Account" (FCS-113).
  const who = useDisplayName()

  // Until the session has resolved, show NEITHER "Log in" nor "Account".
  // Guessing wrong makes the header flip a moment after load, which reads as a
  // glitch to everyone and as a logout to anyone who was signed in.
  const account = !available || !ready ? null : user ? "in" : "out"

  return (
    <header className={s.header} data-print="hide">
      {/* Renders nothing unless THIS tab is viewing somebody's account in test mode. */}
      <ViewAsBanner />
      <div className={`container ${s.inner}`}>
        <a href="/" className={s.logo} aria-label="Free Contractor Services — home">
          <HardHat className={s.logoMark} />
          <span className={s.logoText}>
            <span>Free Contractor</span>
            <span>Services.com</span>
          </span>
        </a>

        <div className={`${s.menu} ${open ? s.menuOpen : ""}`}>
          <nav className={s.nav} aria-label="Primary">
            {LINKS.map(link => (
              <a key={link.label} href={link.href} onClick={() => setOpen(false)}>
                {link.label}
              </a>
            ))}
          </nav>

          <span className={s.actions}>
            {account === "in" && isAdmin && !viewing ? (
              <Link to="/admin/" className={s.account} data-testid="header-admin">
                Admin
              </Link>
            ) : null}

            {account === "in" ? (
              <Link
                to="/account"
                className={`${s.account} ${s.me}`}
                aria-label={`Your account${user?.email ? `, signed in as ${user.email}` : ""}`}
                data-testid="header-account"
              >
                <span className={s.avatar} aria-hidden="true">
                  {who.initial}
                </span>
                <span className={s.meName}>{who.name}</span>
              </Link>
            ) : account === "out" ? (
              <Link to="/log-in" className={s.account}>
                Log in
              </Link>
            ) : null}

            <Link to={cta.to} className={`btn btn--sm ${s.cta}`}>
              {cta.label}
              <ArrowRight className="btn__arrow" />
            </Link>
          </span>
        </div>

        <button
          type="button"
          className={s.toggle}
          aria-expanded={open}
          aria-label={open ? "Close menu" : "Open menu"}
          onClick={() => setOpen(v => !v)}
        >
          <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
            {open ? <path d="M4 4l12 12M16 4L4 16" /> : <path d="M2 5h16M2 10h16M2 15h16" />}
          </svg>
        </button>
      </div>
    </header>
  )
}

export default Header
