import * as React from "react"
import { useAuth } from "../context/auth"

/**
 * What to call the person who is signed in — FCS-113.
 * ============================================================================
 * The header used to say "Account" whether you were signed in as yourself or
 * as nobody ("replace the value in the header so they know they are logged
 * in"). It now shows a small avatar and a name.
 *
 * ── WHERE THE NAME COMES FROM ──────────────────────────────────────────────
 * The profile holds the real one, but the header is on every page and must not
 * make a server call of its own to find it. So each time the account screen
 * loads (or a profile is saved) it leaves the first name in this browser's
 * storage, keyed by who it belongs to, and the header reads that. Until a name
 * has been given, the part of the email before the @ stands in: it is still
 * unmistakably "you are signed in as someone".
 *
 * The key includes the user id so one person signing out and another signing
 * in on the same browser can never be greeted with the previous one's name.
 */

const KEY = id => `fcs-name:${id}`
const EVENT = "fcs-name-changed"

const read = id => {
  try {
    return window.localStorage.getItem(KEY(id)) || ""
  } catch {
    return ""
  }
}

/* Mailboxes that name a role, not a person. "admin@…" greeted as "admin", beside an Admin
   link, read as three admins in a row (FCS-116); a name nobody chose is better left as
   "My account" than shown as the part of an address that happens to be before the @. */
const ROLE_MAILBOXES = [
  "admin", "administrator", "info", "hello", "contact", "support", "office", "sales",
  "mail", "enquiries", "team", "accounts", "noreply", "no-reply", "webmaster", "test",
]

const fallbackName = email => {
  const local = String(email || "").split("@")[0]
  const base = local.split("+")[0].toLowerCase()
  return !local || ROLE_MAILBOXES.includes(base) ? "My account" : local
}

export const firstNameOf = full => String(full || "").trim().split(/\s+/)[0] || ""

/** Called with whatever the server says the name is; an empty name clears it. */
export function rememberName(userId, fullName) {
  if (!userId || typeof window === "undefined") return
  const first = firstNameOf(fullName)
  try {
    if (first) window.localStorage.setItem(KEY(userId), first)
    else window.localStorage.removeItem(KEY(userId))
  } catch {
    /* private mode — the email stands in */
  }
  window.dispatchEvent(new Event(EVENT))
}

export function useDisplayName() {
  const { user } = useAuth()
  const id = user?.id || ""
  const [, tick] = React.useReducer(n => n + 1, 0)

  React.useEffect(() => {
    window.addEventListener(EVENT, tick)
    return () => window.removeEventListener(EVENT, tick)
  }, [])

  if (!id) return { name: "", initial: "" }
  const name = read(id) || fallbackName(user.email)
  return { name, initial: (name[0] || "?").toUpperCase() }
}
