import { useAuth } from "../context/auth"

/**
 * The wording of the main call to action — FCS-103.
 * ============================================================================
 * "Get Started Free" is an invitation to somebody who has not started. Shown to
 * a person who is already signed in — with an account, maybe a website — it
 * reads as though the site has forgotten them. So signed-in people get the
 * same button saying what it actually does for them: it opens the builder.
 *
 * One hook, so the header, the hero and the band at the bottom of the home page
 * cannot disagree about it, and the next person to add a button has somewhere
 * to ask rather than something to copy.
 *
 * ── UNKNOWN IS TREATED AS SIGNED OUT ───────────────────────────────────────
 * The static page is built without knowing who is looking, and the session is
 * restored a moment after it loads. Until it is known the marketing wording is
 * shown, which is right for the visitor the page is built for. Restoring a
 * session is a read from the browser's own storage, so the swap for somebody
 * who IS signed in lands within the first frame or two.
 */
export function useStartCta() {
  const { user, isAffiliate } = useAuth()
  const signedIn = Boolean(user)

  /* An affiliate does not build a website — they make adverts (FCS-110: "this is not
     part of the affiliate account"). */
  if (isAffiliate) return { signedIn, label: "Make an advert", to: "/ad-studio" }

  return {
    signedIn,
    label: signedIn ? "Build my website" : "Get Started Free",
    to: "/website-builder",
  }
}
