import * as React from "react"
import { API_BASE } from "../config/api"

/**
 * Test mode, in the administrator's own browser — FCS-095, FCS-097.
 * ============================================================================
 * Three separate things live here, and keeping them apart is the point:
 *
 *   TEST MODE   a switch on the admin screens. ON (the default): changes to a
 *               customer's plan or domain go to the SANDBOX below and never
 *               reach the server. OFF: they are saved to the real account.
 *               It defaults to ON so that a real change takes a deliberate
 *               act, not a missed click.
 *
 *   SANDBOX     per customer, what the administrator has pretended: "on the
 *               Premium plan", "has sandbox-example.com", "has no domain".
 *               Kept in localStorage, so it is the administrator's alone and
 *               survives a reload. It is never sent anywhere to be stored.
 *
 *   VIEWING     whose account this tab is looking at, if any. Per TAB
 *               (sessionStorage), so closing the tab ends it and a second tab
 *               is never viewing by surprise.
 *
 * ── HOW A SCREEN BECOMES SOMEBODY ELSE'S ───────────────────────────────────
 * While a tab is viewing, every call it makes to the account functions carries
 * three headers (x-view-as, x-as-plan, x-as-domain). The server verifies the
 * caller is an administrator, answers from the CUSTOMER's data with the
 * sandbox laid over it, and refuses every write — see _shared/viewas.ts. It
 * is done once, here, around fetch, because the alternative was threading it
 * through a dozen call sites, and a call site that forgot would be a write
 * that was not refused.
 *
 * Nothing here is a permission. A customer who typed these into their own
 * console would be refused by the server; the browser is only asking.
 */

const MODE_KEY = "fcs-test-mode"
const SANDBOX_PREFIX = "fcs-sandbox:"
const VIEW_KEY = "fcs-view-as"
const EVENT = "fcs-test-mode-change"
const NAME_EVENT = "fcs-view-as-named"

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
export const PLAN_CHOICES = [
  { id: "free", label: "Free" },
  { id: "premium", label: "Premium" },
  { id: "leads", label: "Lead Generation" },
]
const PLAN_IDS = PLAN_CHOICES.map(p => p.id)

/** Storage can be missing or throw (private windows, blocked site data). */
const safely = fn => {
  try {
    return fn()
  } catch {
    return undefined
  }
}
const announce = () => {
  if (typeof window !== "undefined") window.dispatchEvent(new Event(EVENT))
}

// ── the switch ──
export function getTestMode() {
  const stored = safely(() => window.localStorage.getItem(MODE_KEY))
  return stored !== "off"
}
export function setTestMode(on) {
  safely(() => window.localStorage.setItem(MODE_KEY, on ? "on" : "off"))
  announce()
}

// ── the sandbox, one per customer ──
/** { plan?: "free"|"premium"|"leads", domain?: null | "name.com" } — null is "has none". */
export function getSandbox(id) {
  if (!UUID.test(String(id || ""))) return {}
  const raw = safely(() => window.localStorage.getItem(SANDBOX_PREFIX + id))
  if (!raw) return {}
  try {
    const parsed = JSON.parse(raw)
    const out = {}
    if (PLAN_IDS.includes(parsed.plan)) out.plan = parsed.plan
    if (parsed.domain === null) out.domain = null
    else if (typeof parsed.domain === "string" && parsed.domain.trim()) out.domain = parsed.domain.trim().toLowerCase()
    return out
  } catch {
    return {}
  }
}

/** Merges a change in. A key set to `undefined` is cleared (back to "their real one"). */
export function setSandbox(id, patch) {
  if (!UUID.test(String(id || ""))) return
  const next = { ...getSandbox(id), ...patch }
  for (const key of Object.keys(next)) if (next[key] === undefined) delete next[key]
  safely(() => {
    if (Object.keys(next).length) window.localStorage.setItem(SANDBOX_PREFIX + id, JSON.stringify(next))
    else window.localStorage.removeItem(SANDBOX_PREFIX + id)
  })
  announce()
}
export function clearSandbox(id) {
  safely(() => window.localStorage.removeItem(SANDBOX_PREFIX + id))
  announce()
}

// ── whose account this tab is looking at ──
export function getViewAs() {
  const raw = safely(() => window.sessionStorage.getItem(VIEW_KEY))
  if (!raw) return null
  try {
    const parsed = JSON.parse(raw)
    return UUID.test(String(parsed.id || "")) ? { id: parsed.id.toLowerCase(), email: String(parsed.email || "") } : null
  } catch {
    return null
  }
}
export function startViewAs(id, email = "") {
  if (!UUID.test(String(id || ""))) return false
  safely(() => window.sessionStorage.setItem(VIEW_KEY, JSON.stringify({ id: String(id).toLowerCase(), email })))
  announce()
  return true
}
/**
 * Remembers WHOSE account this tab is viewing, once the server has said, so the
 * banner can name them. It announces on its own event: the screens refetch
 * when the sandbox changes, and this must not make them refetch again.
 */
export function rememberViewAsEmail(email) {
  const view = getViewAs()
  if (!view || !email || view.email === email) return
  safely(() => window.sessionStorage.setItem(VIEW_KEY, JSON.stringify({ id: view.id, email })))
  if (typeof window !== "undefined") window.dispatchEvent(new Event(NAME_EVENT))
}

export function stopViewAs() {
  safely(() => window.sessionStorage.removeItem(VIEW_KEY))
  announce()
}

/**
 * Starts viewing when the address says `?viewAs=<id>`, then takes it out of
 * the address so a reload or a shared link does not keep re-opening it.
 * Returns whether this tab is viewing afterwards.
 */
export function adoptViewAsFromUrl() {
  if (typeof window === "undefined") return false
  const wanted = new URLSearchParams(window.location.search).get("viewAs")
  if (wanted && startViewAs(wanted)) {
    const url = new URL(window.location.href)
    url.searchParams.delete("viewAs")
    safely(() => window.history.replaceState(null, "", url.pathname + url.search + url.hash))
  }
  return Boolean(getViewAs())
}

/** The headers a viewing tab adds to its account calls, or null. */
export function viewAsHeaders() {
  const view = getViewAs()
  if (!view) return null
  const sandbox = getSandbox(view.id)
  const headers = { "x-view-as": view.id }
  if (sandbox.plan) headers["x-as-plan"] = sandbox.plan
  if (sandbox.domain !== undefined) headers["x-as-domain"] = sandbox.domain === null ? "none" : sandbox.domain
  return headers
}

/* The functions a customer's account screens call. Admin functions are not in
   this list on purpose: an administrator working on the admin screens is acting
   as themselves. */
const ACCOUNT_FUNCTIONS = [
  "my-account",
  "my-documents",
  "my-profile",
  "qr-tracking",
  "domain-connect",
  "domain-search",
  "create-checkout-session",
  "publish-site",
  "stage-site",
  "affiliate-link",
]

let installed = false
function install() {
  if (installed || typeof window === "undefined" || typeof window.fetch !== "function") return
  installed = true
  const real = window.fetch.bind(window)
  window.fetch = (input, init) => {
    try {
      const url = typeof input === "string" ? input : input?.url || String(input)
      const name = url.startsWith(`${API_BASE}/`) ? url.slice(API_BASE.length + 1).split(/[/?#]/)[0] : ""
      if (ACCOUNT_FUNCTIONS.includes(name)) {
        const extra = viewAsHeaders()
        if (extra) {
          const headers = new Headers(init?.headers || (typeof input === "object" ? input.headers : undefined))
          for (const [key, value] of Object.entries(extra)) headers.set(key, value)
          return real(input, { ...(init || {}), headers })
        }
      }
    } catch {
      /* Never let this get in the way of a call; fall through to the real one. */
    }
    return real(input, init)
  }
}
install()

// ── hooks ──
/** Re-reads `read` whenever any of this module's state changes, in this tab or another. */
function useStored(read) {
  const [value, setValue] = React.useState(null)
  React.useEffect(() => {
    const update = () => setValue(read())
    update()
    window.addEventListener(EVENT, update)
    window.addEventListener(NAME_EVENT, update)
    window.addEventListener("storage", update)
    return () => {
      window.removeEventListener(EVENT, update)
      window.removeEventListener(NAME_EVENT, update)
      window.removeEventListener("storage", update)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])
  return value
}

/** true/false once known; null on the server and the first paint. */
export const useTestMode = () => useStored(getTestMode)
export const useViewAs = () => useStored(getViewAs)

/** A customer's sandbox, live. `{}` when there is none. */
export function useSandbox(id) {
  const [value, setValue] = React.useState({})
  React.useEffect(() => {
    const update = () => setValue(getSandbox(id))
    update()
    window.addEventListener(EVENT, update)
    window.addEventListener("storage", update)
    return () => {
      window.removeEventListener(EVENT, update)
      window.removeEventListener("storage", update)
    }
  }, [id])
  return value
}

/** Calls `fn` when the sandbox or the viewed account changes (so a screen can refetch). */
export function onTestModeChange(fn) {
  if (typeof window === "undefined") return () => {}
  window.addEventListener(EVENT, fn)
  return () => window.removeEventListener(EVENT, fn)
}
